import { useState, useCallback, useEffect } from 'react'
import PropTypes from 'prop-types'
import { Row } from '../../commonStyle/index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import BottomActionSheet from '../BottomActionSheet'
import CustomText from '../CustomText'
import TitleError from '../TitleError'
import { BottomSheetSelectStyle } from './index.style'
import { LANG_STRINGS } from '../../lang'

function BottomSheetSelect ({
  title, required, placeholder, data = [], dataKey = '', displayKey = '',
  onSelect = () => {}, defaultItem, error = '', hideLabel = false,
  bgColor = AgentColorPallette.white, displayBorder = false, className,
  placeholderColor = AgentColorPallette.fontSemiGrey, showReset = false, handlePreClicked
}) {
  const [selectedItem, setSelectedItem] = useState(defaultItem || null)
  const [showBottomSheet, setShowBottomSheet] = useState(false)

  useEffect(() => {
    setSelectedItem(defaultItem)
  }, [defaultItem])

  const handleToggleShowModal = useCallback(() => {
    setShowBottomSheet(showBottomSheet => !showBottomSheet)
    if (handlePreClicked) {
      handlePreClicked()
    }
  }, [handlePreClicked])

  const handleSelectItem = useCallback((item) => {
    let selectItem = item
    if (selectedItem?.[dataKey] === item[dataKey]) {
      selectItem = {}
    }
    setSelectedItem(selectItem)
    onSelect({ ...selectItem })
    setShowBottomSheet(false)
  }, [onSelect, dataKey, selectedItem])

  return (
    <BottomSheetSelectStyle displayBorder={displayBorder} bgColor={bgColor} error={error}>
      {
        !hideLabel &&
          <TitleError
            title={title}
            required={required}
            error={error}
          />
      }
      <Row
        className={className || 'search-type-input'}
        justify='space-between'
        align='center'
        onClick={handleToggleShowModal}
      >
        <CustomText
          color={selectedItem ? AgentColorPallette.black : placeholderColor}
          size='12px'
        >
          {selectedItem?.[displayKey] || placeholder}
        </CustomText>
        <div>
          <i
            className={`fas fa-caret-down ${showBottomSheet ? 'caret-rotate-up' : 'caret-rotate-down'}`}
          />&nbsp;&nbsp;
        </div>
      </Row>
      <BottomActionSheet
        show={showBottomSheet}
        onCloseSheet={() => setShowBottomSheet(false)}
      >
        <Row className='bottom-sheet-title' justify='space-between'>
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            weight={800}
            bottom='0'
          >
            {title}
          </CustomText>
          {
            showReset &&
              <CustomText
                color={AgentColorPallette.maroonRed}
                bottom='0'
                size='13px'
                onClick={() => handleSelectItem({})}
                wight={700}
              >
                {LANG_STRINGS.removeFilter}
              </CustomText>
          }
        </Row>

        {
          Array.isArray(data) && data?.map((item, index) => {
            return (
              <div
                key={`sheet-${index}`}
                className={
                  `
                    sheet-item ${(index + 1) !== data.length ? 'bottom-border' : ''}
                    ${item[dataKey] === selectedItem?.[dataKey] ? 'selected-item-type' : ''}
                  `
                }
                onClick={() => handleSelectItem(item)}
              >
                {item[displayKey]}
              </div>
            )
          })
        }
      </BottomActionSheet>
    </BottomSheetSelectStyle>
  )
}

BottomSheetSelect.propTypes = {
  title: PropTypes.string,
  dataKey: PropTypes.string,
  displayKey: PropTypes.string,
  placeholder: PropTypes.string,
  defaultItem: PropTypes.object,
  onSelect: PropTypes.func,
  required: PropTypes.bool,
  data: PropTypes.array
}

export default BottomSheetSelect
