import { Component } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import { Container, ContentBox, Button, CustomText } from '../../../components'
import { BalanceHistoryWrapper } from './index.style'
import TransactionActions from '../../../redux/transaction/action'
import { NoContent } from './noContent'
import { formatMoney, getQueryParams, isCreditAmount } from '../../../helpers/utility'
import { AgentColorPallette } from '../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../lang'
import BottomSheetSelect from '../../../components/BottomSheetSelect'
import { COMMISSION_WALLET_TRANSACTION_TYPE, POINT_WALLET_TRANSACTION_TYPE } from './constants'
import DatePicker from 'react-mobile-datepicker'

const { getPointsList, getTransactionList } = TransactionActions

const year = 2019

class BalanceHistory extends Component {
  constructor (props) {
    super(props)
    this.state = {
      years: [],
      date: '',
      pageNumber: 1,
      transactionType: '',
      isShowDatepicker: false
    }
    this.walletType = ''
  }

  componentDidMount () {
    this.walletType = getQueryParams('wallet_type')
    const currentYear = moment().year()
    const years = []
    const difference = currentYear - year
    let i = 0
    for (i = 0; i <= difference; i++) {
      years.push({ name: year + i, value: year + i })
    }
    this.setState({ years })
    if (this.walletType === 'points') {
      this.props.getPointsList()
    } else {
      this.props.getTransactionList()
    }
  }

  handleLoadMore = () => {
    const { pageNumber, date, transactionType } = this.state
    const filter = {
      page_size: (pageNumber + 1) * 3
    }

    if (date) {
      filter.created_at_start = moment(date).startOf('month').format('YYYY-MM-DD')
      filter.created_at_end = moment(date).endOf('month').format('YYYY-MM-DD')
    }
    if (transactionType) {
      filter.wallet_category = transactionType
    }
    this.setState({ pageNumber: pageNumber + 1 })
    if (this.walletType === 'points') {
      this.props.getPointsList(filter)
    } else {
      this.props.getTransactionList(filter)
    }
  }

  handleFilter = (flag, value) => {
    const { pageNumber, transactionType, date } = this.state
    const filter = {
      page_size: pageNumber * 3
    }

    if (flag === 'date') {
      this.setState({ date: value })
      if (value) {
        filter.created_at_start = moment(value).startOf('month').format('YYYY-MM-DD')
        filter.created_at_end = moment(value).endOf('month').format('YYYY-MM-DD')
      }
    }
    if (flag === 'transactionType') {
      this.setState({ transactionType: value.key })
      filter.wallet_category = value.key
    }

    if (!filter.created_at_start && flag !== 'date' && date) {
      filter.created_at_start = moment(date).startOf('month').format('YYYY-MM-DD')
      filter.created_at_end = moment(date).endOf('month').format('YYYY-MM-DD')
    }
    if (!filter.wallet_category && flag !== 'transactionType' && transactionType) {
      filter.wallet_category = transactionType
    }

    if (this.walletType === 'points') {
      this.props.getPointsList(filter)
    } else {
      this.props.getTransactionList(filter)
    }
  }

  handleDatepickerToggle = (val) => {
    this.setState({
      isShowDatepicker: val
    })
  }

  render () {
    const { transactionList, transactionListLoading, pointsList, pointLoader } = this.props
    const { pageNumber, isShowDatepicker, date, transactionType } = this.state

    return (
      <Container title='Mutasi Saldo' loader={transactionListLoading || pointLoader}>
        <BalanceHistoryWrapper>
          <div className='select-wrapper'>
            <DatePicker
              showCaption
              isOpen={isShowDatepicker}
              confirmText={
                <CustomText
                  color={AgentColorPallette.fontDarkGrey}
                  size='15px'
                  weight={700}
                >
                  {LANG_STRINGS.select}
                </CustomText>
              }
              cancelText={
                <CustomText
                  color={AgentColorPallette.maroonRed}
                  size='13px'
                  wight={700}
                  onClick={() => this.handleFilter('date', '')}
                >
                  {LANG_STRINGS.removeFilter}
                </CustomText>
              }
              onSelect={(val) => { this.handleFilter('date', val) }}
              onCancel={() => this.handleDatepickerToggle(false)}
              theme='ios'
              dateConfig={{
                month: {
                  format: 'MM',
                  caption: 'Month'
                },
                year: {
                  format: 'YYYY',
                  caption: 'Year'
                }
              }}
            />
            <div className={`input-f ${date ? 'input-f-selected' : ''}`} onClick={() => this.handleDatepickerToggle(true)}>
              {date ? moment(date).format('MMMM-YYYY') : LANG_STRINGS.selectDate}
              <i
                className={`fas fa-caret-down ${isShowDatepicker ? 'caret-rotate-up' : 'caret-rotate-down'}`}
              />&nbsp;&nbsp;
            </div>
            <BottomSheetSelect
              showReset
              hideLabel
              title={LANG_STRINGS.mutationType}
              placeholder={`${LANG_STRINGS.select} ${LANG_STRINGS.mutationType}`}
              placeholderColor={AgentColorPallette.black}
              onSelect={(value) => this.handleFilter('transactionType', value)}
              dataKey='key'
              displayKey='value'
              defaultItem=''
              data={this.walletType === 'points' ? POINT_WALLET_TRANSACTION_TYPE : COMMISSION_WALLET_TRANSACTION_TYPE}
              className={`input-f ${transactionType ? 'input-f-selected' : ''}`}
            />
          </div>
          <div className='transaction-list'>
            {
              (this.walletType === 'points')
                ? (
                pointsList?.data && pointsList.data.length > 0 ? (
                  pointsList.data.map((transaction, index) =>
                    <ContentBox
                      heading={`${transaction.commission_type} ${isCreditAmount(transaction.amount) ? 'setelah Pajak' : ''}`}
                      value={isCreditAmount(transaction.amount) ? '+ ' + formatMoney(transaction.amount, 0) : formatMoney(transaction.amount, 0)}
                      secondRowText={transaction.description}
                      thirdRowText={transaction.transaction_date}
                      color={isCreditAmount(transaction.amount) ? AgentColorPallette.green : AgentColorPallette.error}
                      key={index}
                    />
                  )
                )
                  : (
                    <NoContent text={LANG_STRINGS.walletEmptyStatement} />
                  )
                )
                : (
                  transactionList.data && transactionList.data.length > 0 ? (
                    transactionList.data.map((transaction, index) =>
                      <ContentBox
                        heading={`${transaction.commission_type} ${isCreditAmount(transaction.amount) ? 'setelah Pajak' : ''}`}
                        value={isCreditAmount(transaction.amount) ? '+ ' + formatMoney(transaction.amount, 0) : formatMoney(transaction.amount, 0)}
                        secondRowText={transaction.description}
                        thirdRowText={transaction.transaction_date}
                        color={isCreditAmount(transaction.amount) ? AgentColorPallette.green : AgentColorPallette.error}
                        tax={`Pajak: -${formatMoney(transaction.tax, 0)}`}
                        key={index}
                      />
                    )
                  )
                    : (
                      <NoContent text={LANG_STRINGS.walletEmptyStatement} />
                    )
                )
            }
            {
              ((transactionList.meta_data && transactionList.meta_data.total_records > pageNumber * 3) ||
              (pointsList?.meta_data && pointsList.meta_data.total_records > pageNumber * 3)) &&
                <Button className='load-more-button' onClick={this.handleLoadMore}>TAMPILKAN LAGI</Button>
            }
          </div>
        </BalanceHistoryWrapper>
      </Container>
    )
  }
}

export default connect((state) => ({
  transactionListLoading: state.Loading.GET_TRANSACTION_LIST,
  transactionList: state.Transaction.transactionList,
  pointLoader: state.Loading.GET_POINTS_LIST,
  pointsList: state.Transaction.pointsList
}), {
  getTransactionList,
  getPointsList
})(BalanceHistory)
